import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/* eslint-disable */
import FormDeletion from "@/components/FormDesigner/FormDialogs/FormDeletion.vue";
import FormCreation from "@/components/FormDesigner/FormDialogs/FormCreation.vue";
import EditForms from "@/components/FormDesigner/FormDialogs/EditForms.vue";
import { list_forms_customs } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    FormCreation,
    EditForms,
    SnackBar,
    FormDeletion
  },
  data() {
    return {
      tableData: [],
      SnackBarComponent: {},
      tableLoading: false,
      height: 0,
      headers: [{
        text: "Form Name",
        value: "form_name",
        sortable: false
      }, {
        text: "Form Description",
        value: "form_description",
        sortable: false
      }, {
        text: "Created On",
        value: "form_created_on",
        sortable: false
      }, {
        text: "Form Designed ",
        value: "is_form_designed",
        sortable: false
      }, {
        text: "Flow Designed ",
        value: "is_flow_design",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      componentCheck: 0,
      formCreationDialog: false,
      editFormDialog: false,
      nextToken: null,
      formInfo: {},
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      deleteForm: false
    };
  },
  created() {
    this.height = window.innerHeight - 220;
    this.fetch_forms();
  },
  methods: {
    handle_pagination() {
      if (this.nextToken) {
        this.fetch_forms();
      }
    },
    create_form() {
      this.componentCheck = 1;
      this.formCreationDialog = true;
    },
    fetch_value(val) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    activate_deactivate(value) {
      this.deleteForm = true;
      this.formInfo = value;
      this.componentCheck = 3;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    handleRowClick(value) {
      // console.log(value);
      this.$store.commit("SetformLibrary", false);
      this.$store.commit("SetFormObj", value);
      this.$store.commit("Setpathinfo", "Admin");
      this.$store.commit("SetFormType", "CUSTOM");
      this.$store.commit("SetDirectoryForm", false);
      this.$store.commit("SetExternalForm", false);
      this.$router.push("/home/Forms");
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.formCreationDialog = false;
      this.editFormDialog = false;
      this.deleteForm = false;
      this.fetch_forms();
    },
    edit_form(value) {
      this.componentCheck = 2;
      this.editFormDialog = true;
      this.formInfo = value;
    },
    async fetch_forms() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_forms_customs, {
          input: {
            organization_id: data.organization.organization_id,
            // user_email_id: data.user.user_email_id,
            limit: 51,
            nextToken: this.nextToken
          }
        }));
        this.tableData = [];
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_forms_customs);
        // console.log(response);
        if (response.Status == "SUCCESS") {
          // this.tableData = response.data;
          this.nextToken = response.nextToken;
          let array = this.tableData.concat(response.data);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.form_id === obj.form_id));
          this.tableData = uniqueArrayOfObjects;
          // this.tableData.sort((a, b) =>
          //   a.form_name.localeCompare(b.form_name, undefined, {
          //     sensitivity: "base",
          //   })
          // );
        } else {}
      } catch (error) {
        this.tableLoading = false;
      }
    }
  }
};
